/**
 * Schemas for the messages and enums of `google/protobuf/descriptor.proto`,
 * which describe `.proto` files.
 *
 * **Details**
 *
 * `protoc --descriptor_set_out` and `buf build` write a `FileDescriptorSet`,
 * and protoc plugins receive a `FileDescriptorProto` per file. Every message
 * keeps the fields it does not declare, such as custom options, in its
 * `[Protobuf.unknown]` property, so re-encoding a descriptor keeps them.
 *
 * The module is generated by `protoc-gen-effect` from the `descriptor.proto`
 * of protoc 36.2. Property keys are the lowerCamelCase field names, nested
 * types are joined with `_` (`DescriptorProto.ExtensionRange` is
 * `DescriptorProto_ExtensionRange`), and enum values are their names in
 * `descriptor.proto` (`"TYPE_INT32"` of `FieldDescriptorProto.Type`).
 *
 * **Example** (Reading a descriptor set)
 *
 * ```ts import.meta.vitest
 * import { Schema } from "effect"
 * import { Protobuf, ProtobufDescriptor } from "effect/encoding"
 *
 * const codec = Protobuf.toCodec(ProtobufDescriptor.FileDescriptorSet)
 *
 * // a descriptor set with one file, "user.proto"
 * const bytes = Uint8Array.from([10, 12, 10, 10, ...new TextEncoder().encode("user.proto")])
 * const set = Schema.decodeSync(codec)(bytes)
 *
 * set.file.map((file) => file.name) // => ["user.proto"]
 * ```
 *
 * @stability experimental
 * @since 4.0.6
 */
import * as Schema from "../Schema.ts"
import * as Protobuf from "./Protobuf.ts"

